#!/bin/sh
# Generated by cluster-manager (imagecompose). Change the recipe, not this file.
# One preset job at a fixed interval; credentials come from the service environment or secrets.
set -u
INTERVAL=3600
trap 'exit 0' TERM INT
run_job() {
    restic backup --host dbcm '/data' &&
    restic forget --keep-daily 7 --prune
}
wait_interval() {
    sleep "$INTERVAL" &
    wait $!
}
while true; do
    echo "dbcm-jobs: running restic-backup"
    if run_job; then
        echo "dbcm-jobs: done"
    else
        rc=$?
        echo "dbcm-jobs: failed with status $rc" >&2
        exit "$rc"
    fi
    wait_interval
done
